let primera = base
| summarize primera_vez = min(timestamp) by user_Id;
base
| join kind=inner primera on user_Id
| extend dia = bin(timestamp, 1d), es_nuevo = bin(primera_vez, 1d) == bin(timestamp, 1d)
| summarize nuevos = dcountif(user_Id, es_nuevo), recurrentes = dcountif(user_Id, not(es_nuevo)) by dia
| order by dia asc

